// The library's own Barnes-Hut quad tree (generated by lib/codeGenerators/generateQuadTree.js),
// with one change to the force law: bodies push each other as if they lived in a thin flat
// slab of thickness h. Much closer than h/2 the push falls off as 1/r^2, as today; much farther
// it falls off as 2/(h r), the way a push spreads in a two-dimensional world. The two parts are
// equal at r = h/2, where the push is sqrt(2) times today's (at r = h, sqrt(5) times).
//
//   F = G m_i m_j sqrt(1 + (2r/h)^2) / r^2
//
// (an interpolation of the exact sum over mirror images of a source between two insulating
// walls; within 15% of it everywhere and exact at both ends).
import generateQuadTree from '../../../../lib/codeGenerators/generateQuadTree.js';

let createSlabQuadTree;

// Upper bound on 4/h^2. It only applies when h is below about 1e-50 layout units (or h*h
// underflows to 0), where sqrt(1 + slabK r^2) would overflow and turn positions into NaN.
const MAX_SLAB_K = 1e100;

function getFactory() {
  if (createSlabQuadTree) return createSlabQuadTree;
  let code = generateQuadTree.generateQuadTreeFunctionBody(2);
  code = patch(code, 'function update(sourceBody) {', 'function update(sourceBody) {\n    var slabK = options.slabK;');
  code = patch(code, 'v = gravity * body.mass * sourceBody.mass / (r * r * r);',
    'v = gravity * body.mass * sourceBody.mass * Math.sqrt(1 + slabK * r * r) / (r * r * r);');
  code = patch(code, 'v = gravity * node.mass * sourceBody.mass / (r * r * r);',
    'v = gravity * node.mass * sourceBody.mass * Math.sqrt(1 + slabK * r * r) / (r * r * r);');
  createSlabQuadTree = new Function(code)();
  return createSlabQuadTree;
}

function patch(code, from, to) {
  if (code.indexOf(from) < 0) throw new Error('slabPush: generated quad tree changed, cannot find: ' + from);
  return code.replace(from, to);
}

/**
 * Creates a replacement for the simulator's 'nbody' force: reset forces, push with the slab
 * law, then apply drag the way the library does (skipped for FIRE, which has its own).
 * getH() returns the slab thickness in layout units; it is read every step.
 */
export default function createSlabPush(simulator, getH) {
  const settings = simulator.settings;
  const options = { gravity: settings.gravity, theta: settings.theta, slabK: 0 };
  const tree = getFactory()(options, simulator.random);

  return function slabPush() {
    const bodies = simulator.bodies;
    if (bodies.length === 0) return;
    const h = getH();
    options.slabK = h > 0 ? Math.min(4 / (h * h), MAX_SLAB_K) : 0;
    tree.options({ gravity: settings.gravity, theta: settings.theta });

    const useDrag = settings.integrator !== 'fire';
    const drag = settings.dragCoefficient;
    tree.insertBodies(bodies);
    for (let i = 0; i < bodies.length; ++i) {
      const body = bodies[i];
      if (body.isPinned) continue;
      body.reset();
      tree.updateBodyForce(body);
      if (useDrag) {
        body.force.x -= drag * body.velocity.x;
        body.force.y -= drag * body.velocity.y;
      }
    }
  };
}
